window.InterviewContent.materials.push(
{"id":"tanstack-query:server-state","topic":"tanstack-query","tab":"junior","ordinal":1,"targetLevel":"junior","angles":[],"kind":"question","title":"Какую задачу решает TanStack Query?","shortAnswer":"Управляет асинхронным серверным состоянием: кешем, загрузкой и синхронизацией.","explanation":"Это не замена всем локальным UI-state. Открытость модального окна обычно не требует server-cache.","assessment":{"basic":"Различает server/UI state.","confident":"Называет кеш и refetch. Управляет асинхронным серверным состоянием: кешем, загрузкой и синхронизацией.","deep":"Нет; нужен серверный контракт версий и согласование клиента."},"followUps":[{"kind":"support","question":"Кто является окончательным владельцем полученных серверных данных?","expected":"Сервер; клиентский кеш хранит представление, которое может устареть."},{"kind":"transfer","question":"Два пользователя изменили запись одновременно. Решит ли кеш конфликт?","expected":"Нет; нужен серверный контракт версий и согласование клиента."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Команда хранит ответы API вручную в локальном state. Определите, какую ответственность может взять TanStack Query."},
{"id":"tanstack-query:query-client","topic":"tanstack-query","tab":"junior","ordinal":2,"targetLevel":"junior","angles":[],"kind":"question","title":"Зачем QueryClientProvider?","shortAnswer":"Передаёт QueryClient и его кеш потребителям React.","explanation":"Клиент должен иметь стабильный жизненный цикл. Создание нового QueryClient на каждый render теряет общий кеш.","assessment":{"basic":"Знает provider.","confident":"Сохраняет client identity. Передаёт QueryClient и его кеш потребителям React.","deep":"Потерю прежнего кеша и нестабильный жизненный цикл; нужен устойчивый экземпляр."},"followUps":[{"kind":"support","question":"Где живёт кеш конкретного QueryClient?","expected":"В экземпляре клиента, доступном потребителям соответствующего provider."},{"kind":"transfer","question":"Provider пересоздаёт клиент при каждом рендере. Какой симптом ожидаете?","expected":"Потерю прежнего кеша и нестабильный жизненный цикл; нужен устойчивый экземпляр."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Покажите подключение TanStack Query к React и объясните расположение общего кеша."},
{"id":"tanstack-query:query-key","topic":"tanstack-query","tab":"junior","ordinal":3,"targetLevel":"junior","angles":[],"kind":"question","title":"Для чего queryKey?","shortAnswer":"Идентифицирует запись кеша и зависимости данных.","explanation":"Все параметры, меняющие результат, входят в ключ. Одинаковый ключ для разных контрактов смешает данные.","assessment":{"basic":"Задаёт массив ключа.","confident":"Включает параметры. Идентифицирует запись кеша и зависимости данных.","deep":"Добавить безопасную tenant identity в ключ и согласовать очистку/изоляцию персональных данных, не включать секреты."},"followUps":[{"kind":"support","question":"Должен ли page участвовать в ключе разных страниц?","expected":"Да, если он меняет получаемые данные."},{"kind":"transfer","question":"В приложение добавили tenant, а страницы и фильтры у разных tenant совпадают. Как изменить идентичность?","expected":"Добавить безопасную tenant identity в ключ и согласовать очистку/изоляцию персональных данных, не включать секреты."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Каталог загружается по странице и фильтру. Спроектируйте идентичность запроса и разделение кеша."},
{"id":"tanstack-query:query-function","topic":"tanstack-query","tab":"junior","ordinal":4,"targetLevel":"junior","angles":[],"kind":"question","title":"Что обязана вернуть queryFn?","shortAnswer":"Данные синхронно либо Promise с данными; ошибку нужно бросить или вернуть rejected Promise. Undefined не является успешными данными.","explanation":"QueryFunction допускает T или Promise<T>. При fetch необходимо самому проверить HTTP-status: полученный Response с 500 ещё не является rejection. Query не определяет бизнес-успех по JSON.","assessment":{"basic":"Возвращает данные синхронно или асинхронно.","confident":"Бросает или отклоняет Promise при ошибке. Данные синхронно либо Promise с данными; ошибку нужно бросить или вернуть rejected Promise. Undefined не является успешными данными.","deep":"Явным допустимым значением, например null, по контракту, не undefined."},"followUps":[{"kind":"support","question":"Как queryFn сообщает ошибку?","expected":"Бросает её или возвращает отклонённый promise."},{"kind":"transfer","question":"API отвечает 204. Как обозначить успешное отсутствие объекта?","expected":"Явным допустимым значением, например null, по контракту, не undefined."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Опишите queryFn загрузки пользователя: допустимый успех и ошибки транспорта/API."},
{"id":"tanstack-query:status-flags","topic":"tanstack-query","tab":"junior","ordinal":5,"targetLevel":"junior","angles":[],"kind":"question","title":"Чем isPending отличается от isFetching?","shortAnswer":"Pending означает отсутствие успешных данных; fetching — выполняющийся запрос.","explanation":"Данные могут отображаться при фоновом refetch. Не стоит заменять весь экран spinner при каждом isFetching.","assessment":{"basic":"Различает data и network.","confident":"Сохраняет данные при refetch. Pending означает отсутствие успешных данных; fetching — выполняющийся запрос.","deep":"Он не доказывает активную загрузку; учитывать fetchStatus и паузу."},"followUps":[{"kind":"support","question":"Могут ли успешные данные уже быть при fetching?","expected":"Да, при фоновом обновлении."},{"kind":"transfer","question":"Сеть пропала до первого запроса. Почему одного pending мало для spinner?","expected":"Он не доказывает активную загрузку; учитывать fetchStatus и паузу."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Компонент имеет данные и isFetching. Объясните состояние и выберите индикатор."},
{"id":"tanstack-query:stale-time","topic":"tanstack-query","tab":"junior","ordinal":6,"targetLevel":"junior","angles":[],"kind":"question","title":"Что задаёт staleTime?","shortAnswer":"Как долго данные считаются свежими.","explanation":"Свежесть не равна сроку хранения. По умолчанию данные считаются stale сразу, но это не означает непрерывный refetch.","assessment":{"basic":"Знает freshness.","confident":"Не путает с gcTime. Как долго данные считаются свежими.","deep":"Явно инвалидировать или обновить запрос согласно контракту, не ждать только времени."},"followUps":[{"kind":"support","question":"Удаляет ли истечение staleTime данные?","expected":"Нет; данные становятся устаревшими по политике свежести."},{"kind":"transfer","question":"Данные свежи, но пользователь знает о внешнем изменении. Как обновить?","expected":"Явно инвалидировать или обновить запрос согласно контракту, не ждать только времени."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Неизменный несколько минут справочник часто открывают повторно. Предложите staleTime и объясните влияние."},
{"id":"tanstack-query:gc-time","topic":"tanstack-query","tab":"junior","ordinal":7,"targetLevel":"junior","angles":[],"kind":"question","title":"Для чего gcTime?","shortAnswer":"Определяет удаление неактивной записи кеша после периода без observers.","explanation":"Пока запрос используется, gcTime не таймер очистки отображаемых данных. В браузере default обычно пять минут.","assessment":{"basic":"Знает inactive cache.","confident":"Различает stale/gc. Определяет удаление неактивной записи кеша после периода без observers.","deep":"Нет; визуальная скрытость не равна отсутствию observers."},"followUps":[{"kind":"support","question":"Когда запись становится кандидатом на сборку?","expected":"Когда не имеет активных observers."},{"kind":"transfer","question":"Вкладка закрыта, но компонент всё ещё смонтирован. Начался ли GC автоматически?","expected":"Нет; визуальная скрытость не равна отсутствию observers."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"После ухода со страницы данные остаются в кеше. Объясните gcTime и отличие удаления от устаревания."},
{"id":"tanstack-query:enabled","topic":"tanstack-query","tab":"junior","ordinal":8,"targetLevel":"junior","angles":[],"kind":"question","title":"Как не запускать запрос без нужного id?","shortAnswer":"Использовать enabled либо типобезопасный skipToken по контракту.","explanation":"Отключённый запрос может иметь данные из кеша. Постоянное императивное refetch теряет преимущества декларативных зависимостей.","assessment":{"basic":"Отключает условно.","confident":"Учитывает cached data. Использовать enabled либо типобезопасный skipToken по контракту.","deep":"Включить id в ключ и определить placeholder/отображение при смене."},"followUps":[{"kind":"support","question":"Что нужно дождаться перед запросом с обязательным id?","expected":"Валидного идентификатора."},{"kind":"transfer","question":"ID сменился после первого успеха. Как избежать показа чужих данных?","expected":"Включить id в ключ и определить placeholder/отображение при смене."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Запрос требует ещё неизвестный id. Покажите условный запуск и состояние до появления id."},
{"id":"tanstack-query:mutation","topic":"tanstack-query","tab":"junior","ordinal":9,"targetLevel":"junior","angles":[],"kind":"question","title":"Чем useMutation отличается от useQuery?","shortAnswer":"Mutation описывает явное изменение/действие, query — получение кешируемых данных.","explanation":"Успешная mutation не обновляет все связанные queries автоматически. Нужны инвалидация или точная запись результата.","assessment":{"basic":"Различает чтение и действие.","confident":"Вызывает mutate по событию. Mutation описывает явное изменение/действие, query — получение кешируемых данных.","deep":"Нельзя рассчитывать; нужны UI-политика и серверная защита от дублей."},"followUps":[{"kind":"support","question":"Должна ли запись автоматически запускаться просто от чтения компонента?","expected":"Нет; это явное действие с отдельным жизненным циклом."},{"kind":"transfer","question":"Действие повторили двойным кликом. Дедуплицирует ли mutation запись как query?","expected":"Нельзя рассчитывать; нужны UI-политика и серверная защита от дублей."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Форма создаёт заказ. Выберите query или mutation и опишите путь от клика до результата."},
{"id":"tanstack-query:invalidate-basic","topic":"tanstack-query","tab":"junior","ordinal":10,"targetLevel":"junior","angles":[],"kind":"question","title":"Что делает invalidateQueries?","shortAnswer":"Помечает подходящие queries stale и обычно refetch активных.","explanation":"Инвалидация не обязана удалять прежние данные. Ключ-фильтр определяет область, поэтому структура ключей имеет практическое значение.","assessment":{"basic":"Знает stale-mark.","confident":"Учитывает active refetch. Помечает подходящие queries stale и обычно refetch активных.","deep":"Определить поведение повторного наблюдения или refetchType; не обещать немедленный запрос каждой записи."},"followUps":[{"kind":"support","question":"Стирает ли invalidateQueries данные сразу?","expected":"Нет; помечает подходящие записи stale и обычно обновляет активные."},{"kind":"transfer","question":"Нужная запись сейчас неактивна. Когда пользователь увидит изменения?","expected":"Определить поведение повторного наблюдения или refetchType; не обещать немедленный запрос каждой записи."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"После изменения товара активный список показывает старые данные. Предложите обновление через инвалидацию."},
{"id":"tanstack-query:refetch-basic","topic":"tanstack-query","tab":"junior","ordinal":11,"targetLevel":"junior","angles":[],"kind":"question","title":"Когда нужен ручной refetch?","shortAnswer":"Для явного обновления текущего запроса, если это соответствует UX.","explanation":"Параметры данных меняют через key/state, а не передают как произвольные аргументы refetch. Иначе кеш не отражает зависимость.","assessment":{"basic":"Обновляет текущий query.","confident":"Меняет параметры через key. Для явного обновления текущего запроса, если это соответствует UX.","deep":"Изменить параметры состояния и ключ, чтобы кеш различал результаты."},"followUps":[{"kind":"support","question":"Меняет ли refetch идентичность текущего query?","expected":"Нет; обновляет текущий запрос."},{"kind":"transfer","question":"Пользователь выбрал другой фильтр. Лучше передать его в refetch или изменить ключ?","expected":"Изменить параметры состояния и ключ, чтобы кеш различал результаты."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Добавьте кнопку «Обновить» для текущего query и определите поведение во время запроса."},
{"id":"tanstack-query:error-ui","topic":"tanstack-query","tab":"junior","ordinal":12,"targetLevel":"junior","angles":[],"kind":"question","title":"Как показать ошибку без потери старых данных?","shortAnswer":"Различать первичную ошибку и ошибку фонового refetch.","explanation":"При refetch старые данные могут оставаться полезными. Показать предупреждение и повтор, не превращая экран в пустое состояние.","assessment":{"basic":"Показывает понятный error.","confident":"Сохраняет полезные данные. Различать первичную ошибку и ошибку фонового refetch.","deep":"Последнее успешное обновление и путь восстановления, не скрывая текущую неопределённость."},"followUps":[{"kind":"support","question":"Нужно ли удалять хорошие данные при ошибке фонового запроса?","expected":"Не обязательно; можно сохранить данные с сообщением об устаревании."},{"kind":"transfer","question":"Повторная ошибка не исчезает час. Что дополнительно показать?","expected":"Последнее успешное обновление и путь восстановления, не скрывая текущую неопределённость."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Сравните первый отказ загрузки и ошибку фонового обновления уже видимых данных. Предложите UI."},
{"id":"tanstack-query:select-basic","topic":"tanstack-query","tab":"junior","ordinal":13,"targetLevel":"junior","angles":[],"kind":"question","title":"Для чего select у useQuery?","shortAnswer":"Преобразует данные для observer, не заменяя исходную запись кеша.","explanation":"Несколько потребителей могут выбирать разные представления. Селектор должен быть чистым и учитывать стабильность функции при дорогом вычислении.","assessment":{"basic":"Преобразует результат.","confident":"Различает observer/cache. Преобразует данные для observer, не заменяя исходную запись кеша.","deep":"Не обязательно при том же ключе; он может читать общие исходные данные."},"followUps":[{"kind":"support","question":"Заменяет ли select общие данные кеша?","expected":"Нет; преобразует представление observer."},{"kind":"transfer","question":"Другому компоненту нужен исходный список. Потребуется ли второй сетевой запрос?","expected":"Не обязательно при том же ключе; он может читать общие исходные данные."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Кеш содержит полный список, компоненту нужны имена. Покажите select и объясните владение результатом."},
{"id":"tanstack-query:devtools","topic":"tanstack-query","tab":"junior","ordinal":14,"targetLevel":"junior","angles":[],"kind":"question","title":"Чем полезны Query Devtools?","shortAnswer":"Показывают ключи, данные, observers и состояния запросов.","explanation":"Они помогают проверить гипотезу о refetch и кешировании, но не заменяют network trace и продуктовые тесты.","assessment":{"basic":"Находит query по ключу.","confident":"Сопоставляет stale/fetching. Показывают ключи, данные, observers и состояния запросов.","deep":"Наблюдать запросы и события безопасной телеметрией без секретов и персональных ключей."},"followUps":[{"kind":"support","question":"Что проверить первым при неожиданном повторном запросе?","expected":"Ключ, observers, freshness и состояние запроса."},{"kind":"transfer","question":"В production нельзя поставить devtools. Как сохранить диагностику?","expected":"Наблюдать запросы и события безопасной телеметрией без секретов и персональных ключей."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Экран неожиданно повторяет запросы. Покажите поиск причины через Query Devtools."},
{"id":"tanstack-query:query-copy","topic":"tanstack-query","tab":"junior","ordinal":15,"targetLevel":"junior","angles":[],"kind":"question","title":"Почему не стоит копировать query.data в useState без причины?","shortAnswer":"Появляется второй источник истины и риск рассинхронизации.","explanation":"Для редактируемого draft копия может быть осмысленной, если явно определено принятие новых серверных данных и сброс.","assessment":{"basic":"Видит дублирование.","confident":"Различает view и draft. Появляется второй источник истины и риск рассинхронизации.","deep":"Нет; определить начало черновика, обновление базы, конфликты и момент сохранения."},"followUps":[{"kind":"support","question":"Что происходит при копировании query-data в локальный state?","expected":"Появляются два источника, требующие согласования."},{"kind":"transfer","question":"Данные стали редактируемым черновиком. Всегда ли копия ошибочна?","expected":"Нет; определить начало черновика, обновление базы, конфликты и момент сохранения."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Копирование query.data в useState через effect вызывает рассинхронизацию. Исправьте чтение данных."},
{"id":"tanstack-query:key-hashing","topic":"tanstack-query","tab":"middle","ordinal":1,"targetLevel":"middle","angles":[],"kind":"question","title":"Как Query сравнивает объектные части ключа?","shortAnswer":"Детерминированным hashing сериализуемого ключа; порядок свойств объекта не должен менять смысл.","explanation":"Порядок элементов массива значим. Нестабильные функции и несерилизуемые значения не годятся как надёжные зависимости.","assessment":{"basic":"Различает объект/массив.","confident":"Строит сериализуемые ключи. Детерминированным hashing сериализуемого ключа; порядок свойств объекта не должен менять смысл.","deep":"Использовать сериализуемые параметры данных, а не поведение функции."},"followUps":[{"kind":"support","question":"Обязан ли порядок полей объекта в ключе менять запрос?","expected":"Нет; hashing сериализуемого ключа детерминирован."},{"kind":"transfer","question":"В ключ положили функцию с замыканием. Как исправите идентичность?","expected":"Использовать сериализуемые параметры данных, а не поведение функции."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Ключи содержат объекты с одинаковыми полями в разном порядке. Оцените идентичность запросов."},
{"id":"tanstack-query:dependent-query","topic":"tanstack-query","tab":"middle","ordinal":2,"targetLevel":"middle","angles":[],"kind":"question","title":"Как связать запрос профиля и запрос его проектов?","shortAnswer":"Второй запускается после появления необходимого идентификатора.","explanation":"Если данные независимы, последовательность создаёт waterfall. Иногда endpoint или параллельный запрос устраняет лишнее ожидание.","assessment":{"basic":"Использует enabled.","confident":"Видит waterfall. Второй запускается после появления необходимого идентификатора.","deep":"Сравнить задержку waterfall, переиспользование кеша и серверный контракт."},"followUps":[{"kind":"support","question":"Откуда второй запрос получает обязательный параметр?","expected":"Из успешного результата первого или другого доступного источника."},{"kind":"transfer","question":"Сервер может вернуть оба результата одним endpoint. Как оцените выбор?","expected":"Сравнить задержку waterfall, переиспользование кеша и серверный контракт."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Для проектов сначала нужен id из запроса пользователя. Спроектируйте зависимость и состояния ожидания."},
{"id":"tanstack-query:parallel-query","topic":"tanstack-query","tab":"middle","ordinal":3,"targetLevel":"middle","angles":[],"kind":"question","title":"Как загрузить динамический набор независимых запросов?","shortAnswer":"Использовать useQueries с отдельными ключами.","explanation":"Число hooks нельзя менять циклом useQuery. Для огромного набора нужен лимит на уровне транспорта или API, useQueries не задаёт pool автоматически.","assessment":{"basic":"Выбирает useQueries.","confident":"Соблюдает hook rules. Использовать useQueries с отдельными ключами.","deep":"Дубли ключей и ожидания observers; нормализовать запросы или явно сопоставить результаты."},"followUps":[{"kind":"support","question":"Как сохранить отдельную идентичность запросов списка?","expected":"Дать каждому стабильный ключ с его параметрами."},{"kind":"transfer","question":"Список содержит один id дважды. Что проверите?","expected":"Дубли ключей и ожидания observers; нормализовать запросы или явно сопоставить результаты."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Загрузите данные для переменного списка id параллельно, сохранив соответствие результатов."},
{"id":"tanstack-query:placeholder","topic":"tanstack-query","tab":"middle","ordinal":4,"targetLevel":"middle","angles":[],"kind":"question","title":"Чем placeholderData отличается от initialData?","shortAnswer":"Placeholder живёт у observer; initialData заполняет кеш.","explanation":"InitialData рассматривается как реальные начальные данные, их актуальность зависит от timestamps/staleTime. Placeholder не следует выдавать за подтверждённый ответ.","assessment":{"basic":"Различает cache/observer.","confident":"Учитывает свежесть. Placeholder живёт у observer; initialData заполняет кеш.","deep":"Учитывать placeholder-состояние и не разрешать операции, требующие подтверждённых данных."},"followUps":[{"kind":"support","question":"Записывает ли placeholderData временный результат в общий кеш?","expected":"Нет; он относится к observer."},{"kind":"transfer","question":"Временные данные похожи на настоящие, но неполны. Как избежать ложных действий?","expected":"Учитывать placeholder-состояние и не разрешать операции, требующие подтверждённых данных."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Сравните placeholderData и initialData для первого отображения: владение, кеш и свежесть."},
{"id":"tanstack-query:pagination","topic":"tanstack-query","tab":"middle","ordinal":5,"targetLevel":"middle","angles":[],"kind":"question","title":"Как сохранить предыдущую страницу при смене номера?","shortAnswer":"В v5 использовать placeholderData с keepPreviousData либо эквивалентной функцией.","explanation":"Ключ включает страницу. UI должен различать временные данные и новый ответ, особенно при доступности кнопки следующей страницы.","assessment":{"basic":"Меняет key страницы.","confident":"Использует placeholderData. В v5 использовать placeholderData с keepPreviousData либо эквивалентной функцией.","deep":"Сброс номера/курсора и допустимость показа предыдущих данных другого фильтра."},"followUps":[{"kind":"support","question":"Почему номер страницы входит в ключ?","expected":"Разные страницы содержат разные данные."},{"kind":"transfer","question":"При смене фильтра оставили старую страницу. Что пересмотрите?","expected":"Сброс номера/курсора и допустимость показа предыдущих данных другого фильтра."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"При переходе страницы каталог пустеет. Предложите сохранение контекста на Query v5."},
{"id":"tanstack-query:infinite-query","topic":"tanstack-query","tab":"middle","ordinal":6,"targetLevel":"middle","angles":[],"kind":"question","title":"Как устроены данные useInfiniteQuery?","shortAnswer":"Pages и pageParams описывают последовательность страниц.","explanation":"Нужны initialPageParam и корректный getNextPageParam. Один ключ нельзя использовать и для обычной, и для infinite-формы данных.","assessment":{"basic":"Знает pages/pageParams.","confident":"Задаёт следующий cursor. Pages и pageParams описывают последовательность страниц.","deep":"Конкурентность fetchNextPage, состояние загрузки и отсутствие пропусков/дублей."},"followUps":[{"kind":"support","question":"Зачем хранить pageParams рядом с pages?","expected":"Чтобы связать страницы с параметрами их загрузки."},{"kind":"transfer","question":"Пользователь быстро вызвал загрузку дальше несколько раз. Что проверите?","expected":"Конкурентность fetchNextPage, состояние загрузки и отсутствие пропусков/дублей."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Спроектируйте infinite query для курсорного API: страницы, параметры, следующая загрузка."},
{"id":"tanstack-query:cancel-query","topic":"tanstack-query","tab":"middle","ordinal":7,"targetLevel":"middle","angles":[],"kind":"question","title":"Как отменить сетевую работу queryFn?","shortAnswer":"Передать полученный AbortSignal в поддерживающий его транспорт.","explanation":"Просто размонтирование не всегда отменяет сетевую операцию автоматически. Поведение зависит от использования сигнала и lifecycle query.","assessment":{"basic":"Прокидывает signal.","confident":"Понимает кооперативную отмену. Передать полученный AbortSignal в поддерживающий его транспорт.","deep":"Нет; проверить реальное потребление signal и отдельно защитить применение результата."},"followUps":[{"kind":"support","question":"Куда нужно передать signal из queryFn?","expected":"В транспорт, поддерживающий отмену."},{"kind":"transfer","question":"Транспорт проигнорировал signal. Достаточно ли вызова отмены для остановки сети?","expected":"Нет; проверить реальное потребление signal и отдельно защитить применение результата."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"При уходе со страницы остановите ненужную загрузку. Покажите связь signal с транспортом."},
{"id":"tanstack-query:set-query-data","topic":"tanstack-query","tab":"middle","ordinal":8,"targetLevel":"middle","angles":[],"kind":"question","title":"Когда использовать setQueryData?","shortAnswer":"Когда известен точный новый результат для конкретной записи.","explanation":"Обновление синхронно и иммутабельно. Частичный mutation response нельзя бездумно записывать поверх полного объекта.","assessment":{"basic":"Пишет точный key.","confident":"Не мутирует старые данные. Когда известен точный новый результат для конкретной записи.","deep":"Нет; нужен корректный patch с учётом членства и порядка либо инвалидация."},"followUps":[{"kind":"support","question":"Нужно ли мутировать старый объект кеша на месте?","expected":"Нет; обновлять иммутабельно."},{"kind":"transfer","question":"Ответ содержит только одну запись, а кеш — отфильтрованный список. Можно ли просто заменить список?","expected":"Нет; нужен корректный patch с учётом членства и порядка либо инвалидация."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Mutation вернула полную запись. Обновите её кеш без лишнего запроса и мутации старых данных."},
{"id":"tanstack-query:optimistic-basic","topic":"tanstack-query","tab":"middle","ordinal":9,"targetLevel":"middle","angles":[],"kind":"question","title":"Как устроен типичный optimistic update?","shortAnswer":"Отменить конфликтующие refetch, сохранить snapshot, обновить кеш, откатить при ошибке и согласовать после.","explanation":"Откат одного snapshot может стереть параллельное изменение. Простой рецепт требует оговорки про конкурентность.","assessment":{"basic":"Описывает шаги.","confident":"Возвращает rollback context. Отменить конфликтующие refetch, сохранить snapshot, обновить кеш, откатить при ошибке и согласовать после.","deep":"Нет; он может стереть новое изменение, нужен операционный или версионный контракт."},"followUps":[{"kind":"support","question":"Зачем сохранять прежнее значение до optimistic-обновления?","expected":"Чтобы иметь контекст восстановления при отказе."},{"kind":"transfer","question":"Вторая mutation уже изменила ту же запись. Безопасен ли полный rollback первого снимка?","expected":"Нет; он может стереть новое изменение, нужен операционный или версионный контракт."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Спроектируйте оптимистичное избранное для одной операции: ожидание, отказ, согласование."},
{"id":"tanstack-query:mutation-promises","topic":"tanstack-query","tab":"middle","ordinal":10,"targetLevel":"middle","angles":[],"kind":"question","title":"Зачем возвращать promise из onSuccess?","shortAnswer":"Чтобы mutation оставалась pending до завершения связанной async-работы.","explanation":"Это полезно при ожидании invalidateQueries. Fire-and-forget завершает mutation раньше обновления нужных данных.","assessment":{"basic":"Возвращает invalidate promise.","confident":"Учитывает pending duration. Чтобы mutation оставалась pending до завершения связанной async-работы.","deep":"Разделить успех записи и неудачу синхронизации, не предлагать слепой повтор записи."},"followUps":[{"kind":"support","question":"Как продлить pending до связанной async-работы callback?","expected":"Вернуть или дождаться соответствующего promise по контракту callback."},{"kind":"transfer","question":"Инвалидация завершилась ошибкой после успешной записи. Что покажете?","expected":"Разделить успех записи и неудачу синхронизации, не предлагать слепой повтор записи."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"После записи pending должен сохраняться до обновления списка. Покажите асинхронный callback."},
{"id":"tanstack-query:retry-query","topic":"tanstack-query","tab":"middle","ordinal":11,"targetLevel":"middle","angles":[],"kind":"question","title":"Как настроить retry с учётом ошибок?","shortAnswer":"Разделить временные ошибки и постоянные, ограничить попытки и задержки.","explanation":"В браузере queries по умолчанию повторяются; серверные defaults отличаются. Авторизация и валидация требуют отдельного решения.","assessment":{"basic":"Классифицирует ошибки.","confident":"Настраивает retry function. Разделить временные ошибки и постоянные, ограничить попытки и задержки.","deep":"Ограниченные попытки, backoff с jitter и учёт серверных сигналов ограничения."},"followUps":[{"kind":"support","question":"Имеет ли смысл повторять постоянную ошибку валидации как сетевой сбой?","expected":"Обычно нет; классифицировать ошибки."},{"kind":"transfer","question":"Сотни клиентов одновременно повторяют запрос. Как уменьшить волну?","expected":"Ограниченные попытки, backoff с jitter и учёт серверных сигналов ограничения."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Запрос получает временные и постоянные ошибки. Предложите политику retry и обратную связь."},
{"id":"tanstack-query:structural-sharing","topic":"tanstack-query","tab":"middle","ordinal":12,"targetLevel":"middle","angles":[],"kind":"question","title":"Почему неизменившиеся части query.data сохраняют ссылки?","shortAnswer":"Structural sharing переиспользует равные части JSON-совместимых данных.","explanation":"Это помогает memo и select. Нестандартные типы данных требуют проверки, потому что оптимизация не универсальна для любого объекта.","assessment":{"basic":"Понимает sharing.","confident":"Связывает с рендерами. Structural sharing переиспользует равные части JSON-совместимых данных.","deep":"Допущения structural sharing и формат данных; не обещать тот же результат для всех типов."},"followUps":[{"kind":"support","question":"Что сохраняется при равенстве JSON-совместимых ветвей?","expected":"Их ссылки могут переиспользоваться."},{"kind":"transfer","question":"В данных появились Map и Date. Что перепроверите?","expected":"Допущения structural sharing и формат данных; не обещать тот же результат для всех типов."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Сервер вернул почти прежний JSON. Объясните structural sharing и влияние на ссылки."},
{"id":"tanstack-query:tracked-props","topic":"tanstack-query","tab":"middle","ordinal":13,"targetLevel":"middle","angles":[],"kind":"question","title":"Почему object-rest может ухудшить оптимизацию useQuery?","shortAnswer":"Он читает все свойства результата и расширяет tracked subscriptions.","explanation":"Query отслеживает использованные свойства. Деструктурировать нужные поля лучше, чем собирать rest ради удобства.","assessment":{"basic":"Знает tracked properties.","confident":"Использует точные поля. Он читает все свойства результата и расширяет tracked subscriptions.","deep":"Props, context, родителей и идентичность select; tracked props не объясняют все рендеры."},"followUps":[{"kind":"support","question":"Почему rest-деструктуризация может расширить подписку?","expected":"Читает много свойств результата и делает их отслеживаемыми."},{"kind":"transfer","question":"Компонент читает только data, но часто рендерится. Что ещё исследуете?","expected":"Props, context, родителей и идентичность select; tracked props не объясняют все рендеры."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Rest-деструктуризация результата useQuery сопровождается частыми обновлениями. Объясните tracked properties."},
{"id":"tanstack-query:prefetch","topic":"tanstack-query","tab":"middle","ordinal":14,"targetLevel":"middle","angles":[],"kind":"question","title":"Когда prefetchQuery лучше загрузки после перехода?","shortAnswer":"Когда вероятный следующий экран известен заранее и бюджет загрузки это допускает.","explanation":"Prefetch заполняет тот же кеш по тому же ключу. Избыточный prefetch расходует сеть; staleTime влияет на повторный fetch при mount.","assessment":{"basic":"Совпадает по key.","confident":"Учитывает freshness. Когда вероятный следующий экран известен заранее и бюджет загрузки это допускает.","deep":"Уменьшить спекулятивную загрузку, привязать её к вероятности и бюджету сети."},"followUps":[{"kind":"support","question":"Нужно ли ждать prefetch для отображения текущего экрана?","expected":"Обычно нет; это подготовка вероятного следующего шага."},{"kind":"transfer","question":"Пользователь на дорогом соединении редко открывает детали. Как измените политику?","expected":"Уменьшить спекулятивную загрузку, привязать её к вероятности и бюджету сети."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Спроектируйте prefetch деталей после списка с учётом вероятности перехода и бюджета сети."},
{"id":"tanstack-query:network-mode","topic":"tanstack-query","tab":"middle","ordinal":15,"targetLevel":"middle","angles":[],"kind":"question","title":"Как networkMode влияет на offline-поведение?","shortAnswer":"Определяет, когда запросы могут выполняться и когда приостанавливаются.","explanation":"Paused не равно failed. Выбор online/always/offlineFirst зависит от того, требует ли queryFn сеть или может читать локальный ресурс.","assessment":{"basic":"Различает paused/error.","confident":"Выбирает mode по транспорту. Определяет, когда запросы могут выполняться и когда приостанавливаются.","deep":"Выбрать networkMode по реальному источнику, не считать каждый query сетевым."},"followUps":[{"kind":"support","question":"Одинаковы ли paused и fetching?","expected":"Нет; приостановленный запрос не выполняется прямо сейчас."},{"kind":"transfer","question":"Запрос читает только локальное хранилище. Нужна ли ему блокировка по online?","expected":"Выбрать networkMode по реальному источнику, не считать каждый query сетевым."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Запрос находится в paused без сети. Объясните networkMode и отображение состояния."},
{"id":"tanstack-query:cache-isolation","topic":"tanstack-query","tab":"senior","ordinal":1,"targetLevel":"senior","angles":[],"kind":"case","title":"Как избежать утечки пользовательских данных при SSR?","shortAnswer":"Создавать QueryClient на запрос, не разделять серверный кеш между пользователями.","explanation":"Dehydrated state тоже является публикуемыми данными. Очистка и сериализация должны учитывать секреты и срок жизни запроса.","assessment":{"basic":"Изолирует clients.","confident":"Проверяет dehydrated payload. Создавать QueryClient на запрос, не разделять серверный кеш между пользователями.","deep":"Отмена и очистка или изоляция персонального кеша по identity."},"followUps":[{"kind":"support","question":"Чем опасен один серверный QueryClient для разных пользователей?","expected":"Персональные данные могут попасть в общий кеш."},{"kind":"transfer","question":"На клиенте сменился аккаунт без перезагрузки. Какая аналогичная граница нужна?","expected":"Отмена и очистка или изоляция персонального кеша по identity."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"SSR обслуживает персональные запросы. Спроектируйте жизненный цикл серверного QueryClient. Запросы обрабатываются одновременно в одном процессе, а данные не должны переходить между аккаунтами."},
{"id":"tanstack-query:invalidation-design","topic":"tanstack-query","tab":"senior","ordinal":2,"targetLevel":"senior","angles":[],"kind":"case","title":"Как спроектировать ключи для большого продукта?","shortAnswer":"Использовать иерархию домена, вида ресурса и параметров, согласовав области инвалидации.","explanation":"Factory сокращает расхождения ключей. Слишком широкая инвалидация создаёт лишний трафик, слишком узкая оставляет устаревшие представления.","assessment":{"basic":"Задаёт key hierarchy.","confident":"Выбирает granularity. Использовать иерархию домена, вида ресурса и параметров, согласовав области инвалидации.","deep":"Инвалидировать соответствующую доменную группу или версионный набор, обосновав цену запросов и допустимость устаревших представлений."},"followUps":[{"kind":"support","question":"Что даёт общий префикс ключей домена?","expected":"Контролируемую область групповой инвалидации."},{"kind":"transfer","question":"Сервер прислал событие массового импорта без списка изменённых id. Как выбрать область обновления?","expected":"Инвалидировать соответствующую доменную группу или версионный набор, обосновав цену запросов и допустимость устаревших представлений."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Спроектируйте ключи и инвалидацию для списка, деталей и поиска одной сущности. Полная перезагрузка всех запросов слишком дорога; изменения должны появляться в активном сценарии вовремя."},
{"id":"tanstack-query:concurrent-optimism","topic":"tanstack-query","tab":"senior","ordinal":3,"targetLevel":"senior","angles":[],"kind":"case","title":"Как избежать отката свежего optimistic update старым snapshot?","shortAnswer":"Моделировать операции или версии, применять условный rollback и согласование с сервером.","explanation":"Несколько mutations одной сущности нельзя считать независимыми. Иногда сериализация либо отказ от cache-level optimism надёжнее.","assessment":{"basic":"Находит конфликт.","confident":"Предлагает version/operation model. Моделировать операции или версии, применять условный rollback и согласование с сервером.","deep":"Согласовать подтверждённый результат и оставшиеся операции по версиям, не заменяя всё старым ответом."},"followUps":[{"kind":"support","question":"Почему полный snapshot rollback опасен при двух операциях?","expected":"Он может отменить успешные изменения другой операции."},{"kind":"transfer","question":"Сервер нормализует текст независимо от клиента. Как завершить optimistic-слой?","expected":"Согласовать подтверждённый результат и оставшиеся операции по версиям, не заменяя всё старым ответом."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Две правки одной записи завершаются в обратном порядке, одна отказала. Сохраните успешную правку. Нельзя блокировать вторую правку до ответа первой или откатывать весь интерфейс к старому снимку."},
{"id":"tanstack-query:mutation-idempotency","topic":"tanstack-query","tab":"senior","ordinal":4,"targetLevel":"senior","angles":[],"kind":"case","title":"Что требуется для надёжного повтора mutation?","shortAnswer":"Серверная идемпотентность, понятный retry-policy и явное состояние неизвестного исхода.","explanation":"Query-библиотека не может отменить уже совершённый серверный эффект. Повтор после сетевого разрыва может создать дубль без ключа операции.","assessment":{"basic":"Различает network и effect.","confident":"Использует idempotency key. Серверная идемпотентность, понятный retry-policy и явное состояние неизвестного исхода.","deep":"Идентификатор операции и достаточный контекст проверки статуса/идемпотентного повтора."},"followUps":[{"kind":"support","question":"Доказывает ли timeout отсутствие записи на сервере?","expected":"Нет; исход может быть неизвестен."},{"kind":"transfer","question":"Приложение перезапустилось перед повтором. Что нужно сохранить?","expected":"Идентификатор операции и достаточный контекст проверки статуса/идемпотентного повтора."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Создание заказа завершилось timeout с неизвестным исходом. Спроектируйте безопасный повтор. Сервер мог сохранить заказ до разрыва связи, а повтор не должен создавать дубль."},
{"id":"tanstack-query:ssr-hydration","topic":"tanstack-query","tab":"senior","ordinal":5,"targetLevel":"senior","angles":[],"kind":"case","title":"Как согласовать prefetch сервера и клиента?","shortAnswer":"Передать dehydrated cache и согласованные ключи/данные, настроив freshness под UX.","explanation":"Timestamp влияет на staleTime после hydration. SSR не гарантирует отсутствие refetch; это отдельная политика.","assessment":{"basic":"Описывает dehydration.","confident":"Учитывает updatedAt. Передать dehydrated cache и согласованные ключи/данные, настроив freshness под UX.","deep":"Возраст данных и timestamp при hydration, а не только момент загрузки HTML клиентом."},"followUps":[{"kind":"support","question":"Должны ли сервер и клиент использовать согласованные query keys?","expected":"Да; иначе hydrated данные не соответствуют чтению."},{"kind":"transfer","question":"Серверная выдача закеширована дольше допустимой свежести. Что учитывать?","expected":"Возраст данных и timestamp при hydration, а не только момент загрузки HTML клиентом."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Передайте загруженные queries с сервера в браузер и определите политику первого обновления. Первый клиентский кадр должен совпасть с сервером без ненужного немедленного запроса."},
{"id":"tanstack-query:cache-ownership","topic":"tanstack-query","tab":"senior","ordinal":6,"targetLevel":"senior","angles":[],"kind":"case","title":"Нужно ли нормализовать весь server cache вручную?","shortAnswer":"Не обязательно; Query хранит результаты запросов, а не универсальную нормализованную базу.","explanation":"Дубли сущности между списками требуют стратегии согласования. Инвалидация часто проще ручного редактирования каждой формы данных.","assessment":{"basic":"Различает query/entity cache.","confident":"Сравнивает invalidation и patch. Не обязательно; Query хранит результаты запросов, а не универсальную нормализованную базу.","deep":"Определить затронутые ключи и политику patch/invalidation, не ждать автоматического объединения сущностей."},"followUps":[{"kind":"support","question":"Нормализует ли Query автоматически все копии сущности?","expected":"Нет; обычно хранит результаты отдельных запросов."},{"kind":"transfer","question":"Одно изменение видно в деталях, но не в списке. Как найти владельца согласования?","expected":"Определить затронутые ключи и политику patch/invalidation, не ждать автоматического объединения сущностей."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Сущность встречается в нескольких query-результатах. Определите владельца согласованности представлений. Детали и несколько фильтрованных списков могут быть активны одновременно."},
{"id":"tanstack-query:large-infinite","topic":"tanstack-query","tab":"senior","ordinal":7,"targetLevel":"senior","angles":[],"kind":"case","title":"Как контролировать память длинного infinite feed?","shortAnswer":"Ограничить pages, определить направление курсоров и стратегию возврата пользователя.","explanation":"Удаление страниц меняет возможность прокрутки назад. Виртуализация DOM не уменьшает автоматически объём кешируемых данных.","assessment":{"basic":"Разделяет DOM и cache.","confident":"Использует maxPages по контракту. Ограничить pages, определить направление курсоров и стратегию возврата пользователя.","deep":"Курсоры обратной загрузки, восстановление позиции и понятное ограничение истории."},"followUps":[{"kind":"support","question":"Почему бесконечное накопление страниц расходует память?","expected":"Все сохранённые pages продолжают занимать кеш."},{"kind":"transfer","question":"Старые страницы удалили, а пользователь прокрутил назад. Какой контракт нужен?","expected":"Курсоры обратной загрузки, восстановление позиции и понятное ограничение истории."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Загружены сотни страниц infinite query. Ограничьте память, сохранив понятную навигацию. Пользователь ожидает возврата назад без неожиданного скачка и потери контекста."},
{"id":"tanstack-query:offline-mutations","topic":"tanstack-query","tab":"senior","ordinal":8,"targetLevel":"senior","angles":[],"kind":"case","title":"Как спроектировать offline-очередь изменений?","shortAnswer":"Определить persistence, порядок, конфликт-решение и допустимость повторов.","explanation":"Возобновление mutations после reload требует сериализуемого состояния и доступной mutationFn по defaults. Локальная очередь не является полной синхронизацией.","assessment":{"basic":"Формулирует протокол.","confident":"Учитывает persistence функций. Определить persistence, порядок, конфликт-решение и допустимость повторов.","deep":"Повторно авторизовать на сервере, показать отказы и не считать сохранённую mutation гарантированным действием."},"followUps":[{"kind":"support","question":"Гарантирует ли сохранение очереди возможность безопасного повтора?","expected":"Нет; нужны серверный контракт и разрешение конфликтов."},{"kind":"transfer","question":"Пока клиент offline, права пользователя отозваны. Как обработать очередь?","expected":"Повторно авторизовать на сервере, показать отказы и не считать сохранённую mutation гарантированным действием."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Спроектируйте сохранение действий offline и отправку после reconnect с обработкой конфликтов. Очередь переживает перезапуск приложения; порядок зависимых операций существенен."},
{"id":"tanstack-query:suspense-waterfall","topic":"tanstack-query","tab":"senior","ordinal":9,"targetLevel":"senior","angles":[],"kind":"case","title":"Как избежать waterfall с suspense-запросами?","shortAnswer":"Предзагружать независимые ресурсы либо использовать подходящий parallel suspense API.","explanation":"Первый suspending hook может прервать выполнение до следующего запроса. Обычная последовательная запись hooks не всегда параллельна в suspense.","assessment":{"basic":"Видит suspension order.","confident":"Выбирает prefetch/parallel API. Предзагружать независимые ресурсы либо использовать подходящий parallel suspense API.","deep":"Предзагрузить ресурсы на уровне маршрута либо применить подходящий параллельный Suspense API."},"followUps":[{"kind":"support","question":"Может ли приостановка первого компонента задержать запуск второго?","expected":"Да, при последовательном обнаружении ресурсов."},{"kind":"transfer","question":"Маршрут знает независимые ключи заранее. Как убрать зависимость от порядка рендера?","expected":"Предзагрузить ресурсы на уровне маршрута либо применить подходящий параллельный Suspense API."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Независимые Suspense-данные грузятся последовательно. Найдите waterfall и предложите параллельное получение. Данные независимы, но сетевой бюджет ограничен и нельзя заранее загрузить весь продукт."},
{"id":"tanstack-query:observability-query","topic":"tanstack-query","tab":"senior","ordinal":10,"targetLevel":"senior","angles":[],"kind":"case","title":"Какие метрики нужны data-layer?","shortAnswer":"Частота и длительность запросов, cache hits, retries, ошибки и влияние на пользовательский сценарий.","explanation":"Считать только число useQuery недостаточно. Ключи логов не должны раскрывать персональные фильтры или токены.","assessment":{"basic":"Выбирает измеримые сигналы.","confident":"Связывает с UX. Частота и длительность запросов, cache hits, retries, ошибки и влияние на пользовательский сценарий.","deep":"Возраст данных, время сценария, ошибки и поведение обновления, а не единственную сетевую метрику."},"followUps":[{"kind":"support","question":"Доказывает ли высокий cache-hit хороший UX?","expected":"Нет; данные могут быть слишком устаревшими."},{"kind":"transfer","question":"Количество запросов упало, но жалобы выросли. Что сопоставите?","expected":"Возраст данных, время сценария, ошибки и поведение обновления, а не единственную сетевую метрику."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Определите измерения качества Query-слоя для пользовательского сценария: свежесть, ожидание, ошибки. Нельзя логировать персональные payload; нужны измерения влияния на реальный сценарий."},
{"id":"tanstack-query:auth-switch","topic":"tanstack-query","tab":"senior","ordinal":11,"targetLevel":"senior","angles":[],"kind":"case","title":"Как менять аккаунт без смешения кеша?","shortAnswer":"Отменить старую работу и удалить/изолировать персональные queries при смене identity.","explanation":"Добавление userId в ключ помогает, но старые данные всё ещё могут храниться. Persistence и mutations требуют отдельной очистки.","assessment":{"basic":"Изолирует identity.","confident":"Чистит старую работу. Отменить старую работу и удалить/изолировать персональные queries при смене identity.","deep":"Отмена, изоляция клиента/identity и контроль применимости результата к текущему пользователю."},"followUps":[{"kind":"support","question":"Почему недостаточно поменять только заголовок авторизации fetcher?","expected":"Старые персональные данные и запросы остаются в кеше."},{"kind":"transfer","question":"Старый запрос завершился после очистки. Как закрыть гонку?","expected":"Отмена, изоляция клиента/identity и контроль применимости результата к текущему пользователю."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Аккаунт меняется без reload. Определите порядок отмены и очистки персональных queries. Старые запросы могут завершиться уже после входа нового пользователя."},
{"id":"tanstack-query:realtime-query","topic":"tanstack-query","tab":"senior","ordinal":12,"targetLevel":"senior","angles":[],"kind":"case","title":"Как совместить WebSocket и query cache?","shortAnswer":"Определить порядок событий, версии и применение patch либо invalidation.","explanation":"Потерянные события и reconnect требуют сверки с сервером. Нельзя считать поток гарантированно полным без протокола.","assessment":{"basic":"Выбирает patch/invalidate.","confident":"Учитывает версии. Определить порядок событий, версии и применение patch либо invalidation.","deep":"Запросить согласованный снимок или восстановить журнал, не продолжать patch неизвестного состояния."},"followUps":[{"kind":"support","question":"Можно ли применять события в произвольном порядке?","expected":"Нет, если patch зависит от версии и последовательности."},{"kind":"transfer","question":"После reconnect обнаружен пропуск событий. Что делать?","expected":"Запросить согласованный снимок или восстановить журнал, не продолжать patch неизвестного состояния."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Согласуйте websocket-события с query-кешем и фоновым refetch. События могут дублироваться и приходить после более нового HTTP-снимка."},
{"id":"tanstack-query:query-testing","topic":"tanstack-query","tab":"senior","ordinal":13,"targetLevel":"senior","angles":[],"kind":"case","title":"Как тестировать сложные queries устойчиво?","shortAnswer":"Изолировать QueryClient, управлять сетью и retry, проверять наблюдаемые состояния.","explanation":"Глобальный клиент между тестами смешивает данные. Проверять race и refetch важнее внутренних таймеров библиотеки.","assessment":{"basic":"Создаёт client на тест.","confident":"Контролирует ответы. Изолировать QueryClient, управлять сетью и retry, проверять наблюдаемые состояния.","deep":"Явно настроить retry и управлять ответами/временем, проверяя нужные состояния."},"followUps":[{"kind":"support","question":"Почему тестам полезен отдельный QueryClient?","expected":"Изолирует кеш, observers и фоновые эффекты."},{"kind":"transfer","question":"Тест ошибки ждёт слишком долго из-за retry. Как сделать его детерминированным?","expected":"Явно настроить retry и управлять ответами/временем, проверяя нужные состояния."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Спроектируйте изолированный тест query-экрана: успех, ошибка и фоновое обновление. Фоновые retries и общий кеш не должны делать тест зависимым от времени и порядка запуска."},
{"id":"tanstack-query:freshness-policy","topic":"tanstack-query","tab":"senior","ordinal":14,"targetLevel":"senior","angles":[],"kind":"case","title":"Как выбрать staleTime для разных ресурсов?","shortAnswer":"По допустимой устарелости, частоте изменений и цене запроса.","explanation":"Один глобальный Infinity скрывает изменения. Статическая справочная информация и баланс счёта требуют разных контрактов.","assessment":{"basic":"Связывает freshness с доменом.","confident":"Сравнивает стоимость. По допустимой устарелости, частоте изменений и цене запроса.","deep":"Кешировать отображение и повторно подтвердить цену на сервере при операции."},"followUps":[{"kind":"support","question":"От чего зависит разумный staleTime?","expected":"От допустимого возраста данных и стоимости обновления."},{"kind":"transfer","question":"Цена товара меняется редко, но при покупке критична. Как разделить требования?","expected":"Кешировать отображение и повторно подтвердить цену на сервере при операции."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Сравните политики свежести для профиля, котировок и справочника, обосновав допустимую устарелость. Сетевой бюджет ограничен; для каждого ресурса нужно обосновать цену устаревания."},
{"id":"tanstack-query:data-layer-migration","topic":"tanstack-query","tab":"senior","ordinal":15,"targetLevel":"senior","angles":[],"kind":"case","title":"Как мигрировать ручной fetch на Query постепенно?","shortAnswer":"Выделить ключи и fetcher, выбрать источник истины и переносить потребителей по вертикальным сценариям.","explanation":"Одновременные старый store и новый cache создают рассинхронизацию. Нужен явный период совместимости и удаление двойного владения.","assessment":{"basic":"Планирует вертикальный перенос.","confident":"Избегает двух источников. Выделить ключи и fetcher, выбрать источник истины и переносить потребителей по вертикальным сценариям.","deep":"Явный адаптер/граница владения и вертикальная миграция сценариев с проверкой инвалидации."},"followUps":[{"kind":"support","question":"Чем опасно одновременное владение данными старым store и Query?","expected":"Два несогласованных источника истины."},{"kind":"transfer","question":"Один экран ещё старый, другой уже новый. Как ограничить переход?","expected":"Явный адаптер/граница владения и вертикальная миграция сценариев с проверкой инвалидации."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Перенесите один сценарий с ручного fetch/store на Query с явным владельцем данных. Старые экраны остаются в работе до следующего релиза; нельзя иметь два независимых владельца записи."},
{"id":"tanstack-query:infinity-static","topic":"tanstack-query","tab":"advanced","ordinal":1,"targetLevel":"middle","angles":["nuance"],"kind":"question","title":"Всегда ли staleTime:Infinity запрещает refetch?","shortAnswer":"Нет; ручная инвалидация может сделать данные stale.","explanation":"В новых v5 есть также static с более строгим поведением, поэтому нельзя смешивать эти контракты. Проверять установленную minor-версию.","assessment":{"basic":"Различает freshness и запрет.","confident":"Знает invalidation. Нет; ручная инвалидация может сделать данные stale.","deep":"Версионный ключ и политику static/инвалидации по используемой версии библиотеки; не смешивать разные режимы."},"followUps":[{"kind":"support","question":"Запрещает ли staleTime:Infinity ручную инвалидацию?","expected":"Нет; Infinity не означает запрет инвалидации."},{"kind":"transfer","question":"Данные должны обновляться только новой версией сборки. Что уточните?","expected":"Версионный ключ и политику static/инвалидации по используемой версии библиотеки; не смешивать разные режимы."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Query со staleTime:Infinity обновился после инвалидации. Объясните ожидаемое поведение."},
{"id":"tanstack-query:disabled-status","topic":"tanstack-query","tab":"advanced","ordinal":2,"targetLevel":"middle","angles":["nuance"],"kind":"question","title":"Почему disabled query одновременно pending и idle?","shortAnswer":"У него нет успешных данных, но загрузка не выполняется.","explanation":"Status и fetchStatus — независимые оси. Spinner первичной загрузки лучше связывать с isLoading, учитывающим fetching.","assessment":{"basic":"Различает оси.","confident":"Объясняет pending без сети. У него нет успешных данных, но загрузка не выполняется.","deep":"Учитывать enabled-контракт и fetchStatus/paused, а не один status."},"followUps":[{"kind":"support","question":"Может ли pending-запрос не выполняться?","expected":"Да; без данных и при отключённом запуске."},{"kind":"transfer","question":"После включения запроса сеть offline. Как различить ожидание параметра и сети?","expected":"Учитывать enabled-контракт и fetchStatus/paused, а не один status."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Disabled query без данных показывает pending и idle. Объясните сочетание и индикатор."},
{"id":"tanstack-query:undefined-data","topic":"tanstack-query","tab":"advanced","ordinal":3,"targetLevel":"middle","angles":["nuance"],"kind":"question","title":"Почему queryFn с успешным undefined считается ошибочной?","shortAnswer":"Query-контракт не разрешает undefined как успешное значение данных.","explanation":"Если отсутствие — валидный результат, выразить его null или явным объектом. Это отличается от undefined до первой загрузки.","assessment":{"basic":"Знает запрет.","confident":"Выбирает явное отсутствие. Query-контракт не разрешает undefined как успешное значение данных.","deep":"Явно разделить доменное отсутствие и ошибку по контракту API, не скрывая оба undefined."},"followUps":[{"kind":"support","question":"Допустим ли undefined как успешный результат queryFn?","expected":"Нет."},{"kind":"transfer","question":"Ресурс отсутствует законно, но 404 иногда означает ошибку доступа. Как определить UI?","expected":"Явно разделить доменное отсутствие и ошибку по контракту API, не скрывая оба undefined."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"QueryFn возвращает undefined при законном отсутствии объекта. Исправьте контракт успеха."},
{"id":"tanstack-query:select-throw","topic":"tanstack-query","tab":"advanced","ordinal":4,"targetLevel":"middle","angles":["nuance"],"kind":"question","title":"Почему select не подходит для обычной проверки сетевой ошибки?","shortAnswer":"Он преобразует observer-data и не является основной границей получения ошибочного ответа.","explanation":"Ошибки данных лучше валидировать в queryFn. Это даёт согласованный error-state для всех observers и корректный retry-policy.","assessment":{"basic":"Выносит validation в queryFn.","confident":"Разделяет transform/fetch. Он преобразует observer-data и не является основной границей получения ошибочного ответа.","deep":"Отделить ошибку представления от общего состояния запроса; проверить конкретный контракт select версии библиотеки."},"followUps":[{"kind":"support","question":"Где лучше обнаруживать некорректный ответ API?","expected":"В queryFn или валидирующем fetcher до успешного кеширования."},{"kind":"transfer","question":"Только один observer не может отобразить корректные данные. Как локализовать проблему?","expected":"Отделить ошибку представления от общего состояния запроса; проверить конкретный контракт select версии библиотеки."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Select валидирует ответ и бросает ошибку. Оцените место проверки в используемой версии Query."},
{"id":"tanstack-query:observer-stale","topic":"tanstack-query","tab":"advanced","ordinal":5,"targetLevel":"senior","angles":["nuance"],"kind":"question","title":"Могут ли два observers одного key иметь разный staleTime?","shortAnswer":"Да, часть опций относится к observer, а данные кеша общие.","explanation":"Один компонент может считать данные stale раньше другого. Нельзя моделировать все опции как одно глобальное поле записи.","assessment":{"basic":"Различает observers/cache.","confident":"Объясняет общие данные. Да, часть опций относится к observer, а данные кеша общие.","deep":"Нет; запись общая, изменения кеша видны соответствующим потребителям."},"followUps":[{"kind":"support","question":"Могут ли два observers читать один кеш с разной политикой свежести?","expected":"Да; часть опций относится к observer."},{"kind":"transfer","question":"Один observer требует частое обновление. Изолирует ли второй себя от новых данных?","expected":"Нет; запись общая, изменения кеша видны соответствующим потребителям."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Два observers одного ключа задают разный staleTime. Объясните общие данные и локальную политику."},
{"id":"tanstack-query:dedupe-window","topic":"tanstack-query","tab":"advanced","ordinal":6,"targetLevel":"middle","angles":["nuance"],"kind":"question","title":"Дедуплицирует ли Query любые близкие по времени запросы?","shortAnswer":"Обычно объединяет работу для одного key через текущий promise, а не произвольное временное окно.","explanation":"После завершения следующий refetch зависит от freshness и triggers. Mutation имеет другой смысл и не получает такой же безопасный дедуп по ключу.","assessment":{"basic":"Знает in-flight sharing.","confident":"Различает staleTime. Обычно объединяет работу для одного key через текущий promise, а не произвольное временное окно.","deep":"Нет; это зависит от freshness и триггеров, а не фиксированного окна дедупликации."},"followUps":[{"kind":"support","question":"Что обычно объединяет одновременные query одного ключа?","expected":"Текущий незавершённый promise."},{"kind":"transfer","question":"Первый запрос завершился, второй компонент появился позже. Гарантировано ли отсутствие нового запроса?","expected":"Нет; это зависит от freshness и триггеров, а не фиксированного окна дедупликации."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Два компонента одновременно запрашивают один ключ. Объясните объединение текущей работы."},
{"id":"tanstack-query:initial-stale","topic":"tanstack-query","tab":"advanced","ordinal":7,"targetLevel":"middle","angles":["nuance"],"kind":"question","title":"Почему initialData сразу перезапрашивается?","shortAnswer":"При default staleTime она может уже считаться stale.","explanation":"InitialData заполняет кеш, но не задаёт вечную свежесть. InitialDataUpdatedAt помогает выразить возраст полученного снимка.","assessment":{"basic":"Учитывает staleTime.","confident":"Задаёт timestamp. При default staleTime она может уже считаться stale.","deep":"Согласованный initialDataUpdatedAt и staleTime, чтобы не сбросить реальный возраст."},"followUps":[{"kind":"support","question":"Считается ли initialData автоматически навсегда свежей?","expected":"Нет; действует freshness-политика."},{"kind":"transfer","question":"Данные взяли из другого кеша с известным возрастом. Что передать дополнительно?","expected":"Согласованный initialDataUpdatedAt и staleTime, чтобы не сбросить реальный возраст."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Query получил initialData и сразу начал запрос. Объясните возраст и свежесть начальных данных."},
{"id":"tanstack-query:consecutive-mutate","topic":"tanstack-query","tab":"advanced","ordinal":8,"targetLevel":"senior","angles":["nuance"],"kind":"question","title":"Почему локальный onSuccess у mutate сработал не для каждого вызова?","shortAnswer":"Callbacks, переданные mutate, связаны с текущим observer и имеют особенности при последовательных вызовах и unmount.","explanation":"Callbacks на useMutation и per-call callbacks имеют разный жизненный цикл. Критичное согласование кеша размещать в устойчивом уровне.","assessment":{"basic":"Различает callback-уровни.","confident":"Учитывает unmount. Callbacks, переданные mutate, связаны с текущим observer и имеют особенности при последовательных вызовах и unmount.","deep":"Связать навигацию с актуальным намерением и конкретным promise/операцией; выполнение callback само не доказывает актуальность результата."},"followUps":[{"kind":"support","question":"Равнозначны ли callbacks useMutation и callbacks отдельного mutate?","expected":"Нет; у observer callbacks есть особенности последовательных вызовов и unmount."},{"kind":"transfer","question":"После каждой записи нужно перейти на её страницу, но поздний ответ старой записи не должен менять текущую навигацию. Как согласовать?","expected":"Связать навигацию с актуальным намерением и конкретным promise/операцией; выполнение callback само не доказывает актуальность результата."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Mutate вызывается подряд с callbacks. Определите гарантии при последовательных вызовах и unmount."},
{"id":"tanstack-query:infinite-refetch","topic":"tanstack-query","tab":"advanced","ordinal":9,"targetLevel":"senior","angles":["nuance"],"kind":"question","title":"Почему infinite query refetch может идти по страницам последовательно?","shortAnswer":"Нужно получить актуальные курсоры, чтобы не пропустить и не дублировать записи.","explanation":"Цена растёт с числом сохранённых страниц. MaxPages и серверный cursor-контракт помогают ограничить работу.","assessment":{"basic":"Знает cursor-зависимость.","confident":"Оценивает цену refetch. Нужно получить актуальные курсоры, чтобы не пропустить и не дублировать записи.","deep":"Пропуски, дубли и соответствие всех pageParams актуальной последовательности."},"followUps":[{"kind":"support","question":"Почему старый cursor может стать неверным после изменения данных?","expected":"Предыдущие страницы определяют границы следующей выборки."},{"kind":"transfer","question":"Обновили только первую страницу после удаления элемента. Что проверить?","expected":"Пропуски, дубли и соответствие всех pageParams актуальной последовательности."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Infinite query повторно получает несколько страниц. Объясните связь обновления и курсоров."},
{"id":"tanstack-query:optimistic-delete","topic":"tanstack-query","tab":"advanced","ordinal":10,"targetLevel":"senior","angles":["engineering"],"kind":"case","title":"Как откатить удаление из отфильтрованных списков без порчи других изменений?","shortAnswer":"Хранить операционный контекст и согласовывать версии либо предпочесть invalidation после ответа.","explanation":"Один snapshot всех списков может затереть новые данные. Оптимистический delete должен учитывать фильтры, сортировку и конкурентные операции.","assessment":{"basic":"Находит конфликт snapshot.","confident":"Проектирует условный rollback. Хранить операционный контекст и согласовывать версии либо предпочесть invalidation после ответа.","deep":"Использовать идентичность и версию операции, затем серверный порядок или инвалидацию вместо старого индекса."},"followUps":[{"kind":"support","question":"Почему восстановление всего списка может вернуть чужие удалённые записи?","expected":"Snapshot не учитывает последующие операции."},{"kind":"transfer","question":"Удалённая запись вернулась сервером в другом порядке. Как согласовать?","expected":"Использовать идентичность и версию операции, затем серверный порядок или инвалидацию вместо старого индекса."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Два удаления параллельны, первое отказало. Восстановите запись без отмены второго удаления."},
{"id":"tanstack-query:gc-long-timer","topic":"tanstack-query","tab":"advanced","ordinal":11,"targetLevel":"senior","angles":["nuance"],"kind":"question","title":"Почему огромный gcTime не гарантирует вечное хранение?","shortAnswer":"Есть пределы таймеров среды, reload, eviction и жизненный цикл QueryClient.","explanation":"Для долговременного восстановления нужна persistence с отдельным maxAge и версией. Кеш памяти не является долговременным хранилищем.","assessment":{"basic":"Различает memory/persistence.","confident":"Учитывает timer limits. Есть пределы таймеров среды, reload, eviction и жизненный цикл QueryClient.","deep":"Нет; нужна отдельная persistence-политика с версией и допустимыми данными."},"followUps":[{"kind":"support","question":"Равен ли большой gcTime долговечному хранению на диске?","expected":"Нет; кеш зависит от клиента и среды."},{"kind":"transfer","question":"Вкладка перезагружена до истечения gcTime. Сохранятся ли данные автоматически?","expected":"Нет; нужна отдельная persistence-политика с версией и допустимыми данными."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Команда считает огромный gcTime гарантией постоянного кеша. Оцените реальные ограничения."},
{"id":"tanstack-query:cancel-not-rollback","topic":"tanstack-query","tab":"advanced","ordinal":12,"targetLevel":"middle","angles":["nuance"],"kind":"question","title":"Отменяет ли cancelQueries серверную транзакцию?","shortAnswer":"Нет; отмена клиентской работы не гарантирует откат сервера.","explanation":"Signal прекращает поддерживающую его операцию клиента. Серверный эффект и его статус требуют отдельного API-контракта.","assessment":{"basic":"Разделяет abort/rollback.","confident":"Объясняет серверный эффект. Нет; отмена клиентской работы не гарантирует откат сервера.","deep":"Неизвестный исход первой операции и идемпотентность/статус, иначе возможен дубль."},"followUps":[{"kind":"support","question":"Отменяет ли AbortSignal уже выполненную серверную запись?","expected":"Нет."},{"kind":"transfer","question":"После отмены пользователь нажал повтор. Что проверить перед новой записью?","expected":"Неизвестный исход первой операции и идемпотентность/статус, иначе возможен дубль."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Клиент отменил mutation, но сервер создал запись. Объясните границы отмены и состояние UI."},
{"id":"tanstack-query:persist-sensitive","topic":"tanstack-query","tab":"advanced","ordinal":13,"targetLevel":"senior","angles":["engineering"],"kind":"case","title":"Что опасно сохранять в persistent query cache?","shortAnswer":"Токены, персональные данные и сведения другого аккаунта без явной политики.","explanation":"Persistence расширяет срок жизни данных. Нужны фильтр dehydration, очистка при logout, maxAge и совместимость формата.","assessment":{"basic":"Выбирает разрешённые данные.","confident":"Ограничивает lifetime. Токены, персональные данные и сведения другого аккаунта без явной политики.","deep":"Изоляция identity, очистка при выходе и явный whitelist допустимых данных."},"followUps":[{"kind":"support","question":"Какие данные могут пережить выход при persistence?","expected":"Всё сохранённое по выбранной политике, включая персональное."},{"kind":"transfer","question":"Устройство используется несколькими аккаунтами. Как разделите сохранённый кеш?","expected":"Изоляция identity, очистка при выходе и явный whitelist допустимых данных."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Определите допустимые persistent query-данные, правила очистки и проверки сохранений."},
{"id":"tanstack-query:query-key-secret","topic":"tanstack-query","tab":"advanced","ordinal":14,"targetLevel":"senior","angles":["engineering","nuance"],"kind":"case","title":"Почему токен авторизации не стоит включать прямо в queryKey?","shortAnswer":"Ключ виден в devtools, логах и persistent cache.","explanation":"Для изоляции использовать безопасный identity/tenant key, а credential передавать транспортом. При смене прав всё равно нужна политика инвалидации.","assessment":{"basic":"Не кладёт секрет в key.","confident":"Разделяет identity/credential. Ключ виден в devtools, логах и persistent cache.","deep":"Безопасной идентичностью/областью данных; авторизацию передавать транспортом, не секретным ключом кеша."},"followUps":[{"kind":"support","question":"Где может оказаться query key кроме памяти приложения?","expected":"В devtools, логах и сохранённом кеше."},{"kind":"transfer","question":"Токен меняется, а данные пользователя те же. Чем заменить токен в ключе?","expected":"Безопасной идентичностью/областью данных; авторизацию передавать транспортом, не секретным ключом кеша."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Токен авторизации включили в query key. Оцените наблюдаемость ключа и исправьте контракт."},
{"id":"tanstack-query:query-consistency","topic":"tanstack-query","tab":"advanced","ordinal":15,"targetLevel":"senior","angles":["engineering","nuance"],"kind":"case","title":"Гарантирует ли свежий query cache согласованность нескольких endpoint?","shortAnswer":"Нет; staleTime — клиентская политика, а не серверная транзакция.","explanation":"Согласованный снимок требует серверной версии, агрегирующего endpoint или протокола. Одновременный refetch не доказывает общую точку времени.","assessment":{"basic":"Различает freshness/consistency.","confident":"Находит серверную границу. Нет; staleTime — клиентская политика, а не серверная транзакция.","deep":"Серверный транзакционный/версионный контракт или общий endpoint; клиентская свежесть этого не создаёт."},"followUps":[{"kind":"support","question":"Гарантирует ли staleTime согласованный серверный снимок нескольких ресурсов?","expected":"Нет."},{"kind":"transfer","question":"Баланс и история пришли из разных версий. Как получить строгую согласованность?","expected":"Серверный транзакционный/версионный контракт или общий endpoint; клиентская свежесть этого не создаёт."}],"context":"TanStack Query 5, React; клиентские defaults. SSR, persistence, retries и networkMode нужно задавать с учётом среды.","references":["https://tanstack.com/query/v5/docs/framework/react/guides/important-defaults","https://tanstack.com/query/v5/docs/framework/react/reference/useQuery","https://tanstack.com/query/v5/docs/framework/react/guides/query-invalidation","https://tanstack.com/query/latest/docs/framework/react/reference/type-aliases/QueryFunction"],"verifiedAt":"2026-11-13","question":"Связанные ресурсы читаются отдельными queries с одним staleTime. Оцените гарантируемую согласованность."}
);
